// grammar.test.js -- the TextMate grammar (syntaxes/botlish.tmLanguage.json,
// generated by tools/editor-grammars.tcl) tokenized by VS Code's own engine
// (vscode-textmate over vscode-oniguruma) against the compiler's
// classification of the fixture (test/fixtures/sample.classes.json, the
// token IR's classes, which the generator writes and
// tests/syntax-highlighting.test checks): every keyword, contextual word,
// constant, number, string, character and comment the compiler sees is
// scoped as one, and no name is scoped as a keyword or a constant.

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const grammarPath = path.join(__dirname, '..', 'syntaxes', 'botlish.tmLanguage.json');
const fixtures = path.join(__dirname, 'fixtures');

function engine() {
  try {
    return { textmate: require('vscode-textmate'), oniguruma: require('vscode-oniguruma') };
  } catch {
    return null;
  }
}

// What a token of each class must be scoped as (a scope of the token's
// stack, innermost last), and what a name must not be.
const expected = {
  keyword: /^keyword\.(control|other|operator\.word)\.botlish$/,
  word: /^keyword\.other\.contextual\.botlish$/,
  constant: /^constant\.language\.botlish$/,
  number: /^constant\.numeric\./,
  string: /^string\.quoted\.double\.botlish$/,
  char: /^string\.quoted\.single\.botlish$/,
  comment: /^comment\./,
};
const notAName = /^(keyword\.(control|other)|constant\.language)\./;

async function tokenizer() {
  const { textmate, oniguruma } = engine();
  const wasm = fs.readFileSync(require.resolve('vscode-oniguruma/release/onig.wasm'));
  await oniguruma.loadWASM(wasm.buffer.slice(wasm.byteOffset, wasm.byteOffset + wasm.byteLength));
  const registry = new textmate.Registry({
    onigLib: Promise.resolve({
      createOnigScanner: (sources) => new oniguruma.OnigScanner(sources),
      createOnigString: (text) => new oniguruma.OnigString(text),
    }),
    loadGrammar: async (scope) => (scope === 'source.botlish'
      ? textmate.parseRawGrammar(fs.readFileSync(grammarPath, 'utf8'), grammarPath)
      : null),
  });
  const grammar = await registry.loadGrammar('source.botlish');
  return (text) => {
    let stack = textmate.INITIAL;
    return text.split('\n').map((line) => {
      const result = grammar.tokenizeLine(line, stack);
      stack = result.ruleStack;
      return result.tokens;
    });
  };
}

test('the grammar is a TextMate grammar of source.botlish', () => {
  const grammar = JSON.parse(fs.readFileSync(grammarPath, 'utf8'));
  assert.equal(grammar.scopeName, 'source.botlish');
  assert.ok(grammar.repository.contextual.patterns.length > 0);
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  assert.deepEqual(manifest.contributes.grammars,
    [{ language: 'botlish', scopeName: 'source.botlish', path: './syntaxes/botlish.tmLanguage.json' }]);
});

test('the grammar scopes the fixture as the compiler classifies it',
  { skip: engine() ? false : 'vscode-textmate and vscode-oniguruma are not installed (npm ci)' },
  async () => {
    const tokenize = await tokenizer();
    const lines = tokenize(fs.readFileSync(path.join(fixtures, 'sample.bot'), 'utf8'));
    const classes = fs.readFileSync(path.join(fixtures, 'sample.classes.json'), 'utf8')
      .split('\n').filter((l) => l !== '').map((l) => JSON.parse(l));
    const problems = [];
    for (const [line, character, length, cls] of classes) {
      const token = lines[line].find((t) => t.startIndex <= character && character < t.endIndex);
      const scopes = token ? token.scopes : [];
      const text = `line ${line + 1}, character ${character + 1} (${cls}, ${length} long)`;
      if (cls === 'identifier') {
        if (scopes.some((s) => notAName.test(s))) {
          problems.push(`${text}: a name scoped ${scopes.join(' ')}`);
        }
      } else if (expected[cls] && !scopes.some((s) => expected[cls].test(s))) {
        problems.push(`${text}: scoped ${scopes.join(' ')}`);
      }
    }
    assert.deepEqual(problems, []);
  });
